import React, { useState } from 'react';

// TypeScript interfaces define the shape of our data
interface Todo {
  id: number;
  text: string;
  completed: boolean;
}

// Component with TypeScript props
interface TodoItemProps {
  todo: Todo;
  onToggle: (id: number) => void;
  onDelete: (id: number) => void;
}

function TodoItem({ todo, onToggle, onDelete }: TodoItemProps) {
  return (
    <div style={{
      display: 'flex',
      alignItems: 'center',
      gap: '8px',
      padding: '8px',
      borderBottom: '1px solid #eee'
    }}>
      <input
        type="checkbox"
        checked={todo.completed}
        onChange={() => onToggle(todo.id)}
      />
      <span style={{
        textDecoration: todo.completed ? 'line-through' : 'none',
        flex: 1
      }}>
        {todo.text}
      </span>
      <button onClick={() => onDelete(todo.id)}>
        ✖
      </button>
    </div>
  );
}

// Main App component
function App() {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [input, setInput] = useState('');

  const addTodo = () => {
    if (!input.trim()) return;

    const newTodo: Todo = {
      id: Date.now(),
      text: input,
      completed: false,
    };

    setTodos([...todos, newTodo]);
    setInput('');
  };

  const toggleTodo = (id: number) => {
    setTodos(todos.map(todo =>
      todo.id === id ? { ...todo, completed: !todo.completed } : todo
    ));
  };

  const deleteTodo = (id: number) => {
    setTodos(todos.filter(todo => todo.id !== id));
  };

  return (
    <div style={{ maxWidth: '400px', margin: '0 auto', padding: '20px' }}>
      <h1>Todo App</h1>

      <div style={{ display: 'flex', gap: '8px', marginBottom: '16px' }}>
        <input
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && addTodo()}
          placeholder="What needs to be done?"
          style={{ flex: 1, padding: '8px' }}
        />
        <button onClick={addTodo}>Add</button>
      </div>

      <div>
        {todos.map(todo => (
          <TodoItem
            key={todo.id}
            todo={todo}
            onToggle={toggleTodo}
            onDelete={deleteTodo}
          />
        ))}
      </div>

      <p>{todos.filter(t => !t.completed).length} items remaining</p>
    </div>
  );
}

export default App;

// pages/api/todos.ts - Next.js API Route
import type { NextApiRequest, NextApiResponse } from 'next';

// In-memory database (replace with PostgreSQL/MongoDB in production)
let todos = [
  { id: 1, text: 'Learn Next.js', completed: false },
  { id: 2, text: 'Build something cool', completed: false },
];

// CRUD API for todos
export default function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  switch (req.method) {
    case 'GET':
      // Return all todos
      res.status(200).json(todos);
      break;

    case 'POST':
      // Create new todo
      const { text } = req.body;
      const newTodo = {
        id: Date.now(),
        text,
        completed: false,
      };
      todos.push(newTodo);
      res.status(201).json(newTodo);
      break;

    case 'PUT':
      // Update a todo (toggle complete)
      const { id, completed } = req.body;
      todos = todos.map(t =>
        t.id === id ? { ...t, completed } : t
      );
      res.status(200).json({ success: true });
      break;

    case 'DELETE':
      // Delete a todo
      const todoId = parseInt(req.query.id as string);
      todos = todos.filter(t => t.id !== todoId);
      res.status(200).json({ success: true });
      break;

    default:
      res.setHeader('Allow', ['GET', 'POST', 'PUT', 'DELETE']);
      res.status(405).end(`Method ${req.method} Not Allowed`);
  }
}
